package dev.fieldnotes.oibsip2;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Typeface;import android.text.InputType;import android.view.*;import android.widget.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;import java.util.concurrent.TimeUnit;

public class MainActivity extends Activity {
 static final int INK=0xff262724,PAPER=0xfff4f0e8,ACC=0xffd65b3f,MUTED=0xff76756e,LINE=0xffd7d0c5,WHITE=0xffffffff;
 LinearLayout page; Db db; long uid=-1; String user=""; Handler handler=new Handler(); long elapsed=0,base=0; boolean running=false,resumeAfterPause=false; Runnable tick; TextView watch; ArrayList<String> laps=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);setContentView(R.layout.activity_main);db=new Db(this);home();}
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(22),dp(18),dp(22),dp(24));return l;} TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setFontFeatureSettings("kern");if(bold)v.setTypeface(Typeface.create("sans-serif-medium",0));return v;} void start(String eyebrow,String title,String sub){page=column();page.setBackgroundColor(PAPER);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(page);setContentView(sc);TextView e=text(eyebrow.toUpperCase(Locale.ROOT),11,ACC,true);e.setLetterSpacing(.13f);page.addView(e,margin(0,0,0,13));TextView t=text(title,32,INK,false);t.setTypeface(Typeface.create("serif",Typeface.NORMAL));page.addView(t,margin(0,0,0,6));if(sub!=null){TextView s=text(sub,14,MUTED,false);page.addView(s,margin(0,0,0,22));}View rule=new View(this);rule.setBackgroundColor(LINE);page.addView(rule,new LinearLayout.LayoutParams(-1,dp(1)));page.addView(new View(this),new LinearLayout.LayoutParams(1,dp(16)));} LinearLayout.LayoutParams margin(int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}
 void add(View v){page.addView(v,margin(0,5,0,5));} TextView label(String s){return text(s,13,MUTED,true);} TextView button(String s,Runnable r){TextView b=text(s,15,WHITE,true);b.setGravity(17);b.setPadding(dp(16),dp(14),dp(16),dp(14));b.setBackground(bg(ACC,12));b.setOnClickListener(v->{v.animate().scaleX(.98f).scaleY(.98f).setDuration(90).withEndAction(()->{v.animate().scaleX(1).scaleY(1).setDuration(140).start();r.run();}).start();});return b;} TextView secondary(String s,Runnable r){TextView b=text(s,14,INK,true);b.setGravity(17);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackground(bg(0xffe7e1d7,12));b.setOnClickListener(v->r.run());return b;} android.graphics.drawable.GradientDrawable bg(int c,int rad){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(c);d.setCornerRadius(dp(rad));return d;} EditText field(String hint,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setTextSize(16);e.setInputType(type);e.setPadding(dp(14),dp(13),dp(14),dp(13));e.setBackground(bg(WHITE,10));return e;} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();} void home(){start("FIELDNOTES     /     ANDROID KIT","Five useful instruments","OIBSIP  ·  JAVA + XML  ·  LOCAL-FIRST");String[] n={"01   Unit converter","02   To-do / sign in","03   Calculator","04   General knowledge quiz","05   Stopwatch / laps"};Runnable[] a={this::converter,this::auth,this::calculator,this::quizIntro,this::stopwatch};for(int i=0;i<n.length;i++){final int k=i;TextView row=text(n[i]+"     ↗",19,INK,true);row.setPadding(dp(17),dp(21),dp(12),dp(21));row.setBackground(bg(WHITE,9));row.setOnClickListener(v->a[k].run());add(row);}add(new View(this),new LinearLayout.LayoutParams(1,dp(20)));add(text("A small field kit, not one app pretending to be five.",14,MUTED,false));}
 void back(){TextView b=secondary("←   Studio index",this::home);add(b);}
 // Unit converter
 final String[][] UNITS={{"Metres","Centimetres","Kilometres","Miles","Feet","Inches"},{"Kilograms","Grams","Pounds","Ounces"},{"Litres","Millilitres","US gallons","Cups"},{"Celsius","Fahrenheit","Kelvin"}}; final String[] CATS={"Length","Mass","Volume","Temperature"};
 void converter(){start("01    /    MEASURE","Unit converter","Four categories · precise factors · no network needed");Spinner cat=spinner(CATS);add(label("MEASUREMENT"));add(cat);add(label("VALUE"));EditText val=field("e.g. 12.5",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);add(val);Spinner from=spinner(UNITS[0]),to=spinner(UNITS[0]);add(label("FROM / TO"));add(from);add(to);TextView out=text("Result appears here",24,INK,true);out.setPadding(dp(14),dp(18),dp(14),dp(18));out.setBackground(bg(0xffe8e2d8,10));add(out);cat.setOnItemSelectedListener(new SimpleSelect(()->{int i=cat.getSelectedItemPosition();setSpin(from,UNITS[i]);setSpin(to,UNITS[i]);out.setText("Result appears here");}));add(button("Swap units",()->{int x=from.getSelectedItemPosition(),y=to.getSelectedItemPosition();from.setSelection(y);to.setSelection(x);}));add(button("Convert",()->{try{String raw=val.getText().toString().trim();if(raw.isEmpty())throw new Exception();double x=Double.parseDouble(raw);int c=cat.getSelectedItemPosition();double z=convert(x,c,from.getSelectedItemPosition(),to.getSelectedItemPosition());out.setText(String.format(Locale.US,"%.8g  %s",z,UNITS[c][to.getSelectedItemPosition()]));}catch(Exception ex){toast("Enter a valid number to convert.");}}));back();}
 Spinner spinner(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;} void setSpin(Spinner s,String[] a){s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));} double convert(double x,int c,int f,int t){if(c==3){double k=f==0?x+273.15:f==1?(x-32)*5/9+273.15:x;return t==0?k-273.15:t==1?(k-273.15)*9/5+32:k;} double[][] factor={{1,.01,1000,1609.344,.3048,.0254},{1,.001,.45359237,.028349523125},{1,.001,3.785411784,.2365882365}};return x*factor[c][f]/factor[c][t];} class SimpleSelect implements AdapterView.OnItemSelectedListener{Runnable r;boolean first=true;SimpleSelect(Runnable x){r=x;}public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int pos,long id){if(first){first=false;return;}r.run();}}
 // Accounts/tasks
 void auth(){if(uid>=0){tasks();return;}start("02    /    PERSONAL LISTS","Your account","Tasks stay on this device and are isolated per account.");EditText email=field("Email address",33),pw=field("Password (8+ characters)",129);add(label("SIGN IN"));add(email);add(pw);add(button("Sign in",()->login(email.getText().toString().trim(),pw.getText().toString())));add(secondary("Create a local account",()->register()));back();}
 void register(){start("02    /    PERSONAL LISTS","Create account","Choose a demo password you do not use elsewhere.");EditText name=field("Name",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS),email=field("Email address",33),pw=field("Password (8+ characters)",129);add(name);add(email);add(pw);add(button("Register",()->{String n=name.getText().toString().trim(),e=email.getText().toString().trim(),p=pw.getText().toString();if(n.isEmpty()||!e.contains("@")||p.length()<8){toast("Add a name, valid email, and password of at least 8 characters.");return;}try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);String hash=hash(p,salt);SQLiteDatabase d=db.getWritableDatabase();d.execSQL("INSERT INTO users(name,email,salt,hash) VALUES(?,?,?,?)",new Object[]{n,e,android.util.Base64.encodeToString(salt,android.util.Base64.NO_WRAP),hash});login(e,p);}catch(Exception ex){toast("That email is already registered.");}}));add(secondary("Back to sign in",this::auth));}
 String hash(String p,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),salt,120000,256);return android.util.Base64.encodeToString(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded(),android.util.Base64.NO_WRAP);}
 void login(String e,String p){try{Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,salt,hash FROM users WHERE email=?",new String[]{e});if(!c.moveToFirst()){c.close();toast("Account not found. Register first.");return;}byte[] salt=android.util.Base64.decode(c.getString(2),android.util.Base64.DEFAULT);String expect=c.getString(3);boolean ok=MessageDigest.isEqual(android.util.Base64.decode(expect,android.util.Base64.DEFAULT),Base64.getDecoder().decode(hash(p,salt)));if(ok){uid=c.getLong(0);user=c.getString(1);c.close();tasks();}else{c.close();toast("Password did not match.");}}catch(Exception x){toast("Could not sign in. Try again.");}}
 void tasks(){start("02    /    PERSONAL LISTS","Hello, "+user,"Your list is stored locally and belongs only to your account.");add(button("＋   Add a task",()->addTask()));add(secondary("Sign out",()->{uid=-1;user="";auth();}));Cursor c=db.getReadableDatabase().rawQuery("SELECT id,title,note,done FROM tasks WHERE user_id=? ORDER BY id DESC",new String[]{""+uid});if(!c.moveToFirst())add(text("Nothing on the list yet. Add one small next step.",16,MUTED,false));else{do{long id=c.getLong(0);String title=c.getString(1),note=c.getString(2);boolean done=c.getInt(3)==1;LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(dp(12),dp(12),dp(12),dp(12));row.setBackground(bg(WHITE,9));TextView t=text((done?"✓   ":"○   ")+title,17,done?MUTED:INK,true);if(done)t.setPaintFlags(t.getPaintFlags()|16);row.addView(t);if(note!=null&&!note.isEmpty())row.addView(text(note,13,MUTED,false));LinearLayout actions=new LinearLayout(this);TextView toggle=secondary(done?"Reopen":"Complete",()->{db.getWritableDatabase().execSQL("UPDATE tasks SET done=? WHERE id=? AND user_id=?",new Object[]{done?0:1,id,uid});tasks();});TextView del=secondary("Delete",()->new AlertDialog.Builder(this).setMessage("Permanently delete this task?").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->{db.getWritableDatabase().execSQL("DELETE FROM tasks WHERE id=? AND user_id=?",new Object[]{id,uid});tasks();}).show());actions.addView(toggle,new LinearLayout.LayoutParams(0,-2,1));actions.addView(del,new LinearLayout.LayoutParams(0,-2,1));row.addView(actions);add(row);}while(c.moveToNext());}c.close();back();}
 void addTask(){LinearLayout box=new LinearLayout(this);box.setPadding(dp(18),dp(8),dp(18),dp(4));box.setOrientation(1);EditText title=field("Task name",1),note=field("Optional notes",1);box.addView(title);box.addView(note);new AlertDialog.Builder(this).setTitle("Add a task").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String t=title.getText().toString().trim();if(t.isEmpty()){toast("A task needs a name.");return;}db.getWritableDatabase().execSQL("INSERT INTO tasks(user_id,title,note,done) VALUES(?,?,?,0)",new Object[]{uid,t,note.getText().toString().trim()});tasks();}).show();}
 static class Db extends SQLiteOpenHelper{Db(Context c){super(c,"fieldnotes.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,salt TEXT NOT NULL,hash TEXT NOT NULL)");d.execSQL("CREATE TABLE tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,note TEXT,done INTEGER NOT NULL DEFAULT 0)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}}
 // Calculator with recursive-descent precedence parser
 String expr="";TextView display;void calculator(){start("03    /    ARITHMETIC","Calculator","A small arithmetic instrument · multiply before adding");display=text("0",38,INK,true);display.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);display.setPadding(dp(16),dp(24),dp(16),dp(24));display.setBackground(bg(WHITE,10));add(display);String[][] keys={{"7","8","9","÷"},{"4","5","6","×"},{"1","2","3","−"},{"C","0",".","+"},{"⌫","="}};for(String[] row:keys){LinearLayout line=new LinearLayout(this);for(String k:row){TextView b=secondary(k,()->tap(k));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(58),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));line.addView(b,p);}add(line);}back();}void tap(String k){if(k.equals("C")){expr="";display.setText("0");return;}if(k.equals("⌫")){if(!expr.isEmpty())expr=expr.substring(0,expr.length()-1);display.setText(expr.isEmpty()?"0":expr);return;}if(k.equals("=")){try{double v=new Parser(expr.replace('×','*').replace('÷','/').replace('−','-')).parse();if(!Double.isFinite(v))throw new Exception();expr=String.valueOf(v);display.setText(expr);}catch(Exception e){expr="";display.setText("Error");}return;}if(display.getText().toString().equals("Error"))expr="";if("+−×÷".contains(k)){if(expr.isEmpty()&&k.equals("−")){expr="-";}else if(!expr.isEmpty()&&"+-*/".indexOf(expr.charAt(expr.length()-1))>=0)expr=expr.substring(0,expr.length()-1)+(k.equals("×")?"*":k.equals("÷")?"/":k.equals("−")?"-":k);else expr+=k.equals("×")?"*":k.equals("÷")?"/":k.equals("−")?"-":k;}else expr+=k;display.setText(expr.replace('*','×').replace('/','÷').replace('-','−'));}
 static class Parser{String s;int i;Parser(String s){this.s=s;}double parse(){double x=sum();if(i!=s.length())throw new RuntimeException();return x;}double sum(){double x=prod();while(i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-')){char o=s.charAt(i++);double y=prod();x=o=='+'?x+y:x-y;}return x;}double prod(){double x=atom();while(i<s.length()&&(s.charAt(i)=='*'||s.charAt(i)=='/')){char o=s.charAt(i++);double y=atom();if(o=='/'&&y==0)throw new ArithmeticException();x=o=='*'?x*y:x/y;}return x;}double atom(){int st=i;if(i<s.length()&&(s.charAt(i)=='-'||s.charAt(i)=='+'))i++;while(i<s.length()&&(Character.isDigit(s.charAt(i))||s.charAt(i)=='.'))i++;if(i==st)throw new RuntimeException();return Double.parseDouble(s.substring(st,i));}}
 // Quiz
 String[][] Q={{"Which planet is known as the Red Planet?","Venus","Mars","Jupiter","Mercury","Mars"},{"What is the largest ocean?","Atlantic","Indian","Pacific","Arctic","Pacific"},{"How many sides has a hexagon?","Five","Six","Seven","Eight","Six"},{"What is the chemical symbol for gold?","Ag","Go","Gd","Au","Au"},{"Which gas do plants absorb?","Oxygen","Carbon dioxide","Nitrogen","Hydrogen","Carbon dioxide"},{"What is the capital of Japan?","Kyoto","Osaka","Tokyo","Sapporo","Tokyo"},{"Which animal is a mammal?","Shark","Dolphin","Trout","Octopus","Dolphin"},{"How many minutes are in two hours?","100","110","120","140","120"},{"Which is the closest star to Earth?","Sirius","The Sun","Proxima Centauri","Vega","The Sun"},{"What is the largest land animal?","Giraffe","African elephant","Polar bear","Hippopotamus","African elephant"}};int[] order;int qi=0,score=0,answered=-1;ArrayList<RadioButton> opts;void quizIntro(){start("04    /    GENERAL KNOWLEDGE","Ten questions. One run.","Questions are shuffled each time. No timer; think it through.");add(button("Start quiz",()->startQuiz()));back();}void startQuiz(){order=new int[Q.length];for(int i=0;i<order.length;i++)order[i]=i;Random r=new Random();for(int i=order.length-1;i>0;i--){int j=r.nextInt(i+1),z=order[i];order[i]=order[j];order[j]=z;}qi=score=0;showQ();}void showQ(){start("04    /    QUESTION "+(qi+1)+" OF "+Q.length,"Choose one answer","Score so far: "+score+" correct");String[] q=Q[order[qi]];add(text(q[0],22,INK,true));RadioGroup g=new RadioGroup(this);opts=new ArrayList<>();for(int i=1;i<=4;i++){RadioButton b=new RadioButton(this);b.setText(q[i]);b.setTextSize(16);b.setTextColor(INK);b.setPadding(dp(10),dp(8),dp(8),dp(8));g.addView(b);opts.add(b);}add(g);TextView feedback=text("Select an answer to see feedback.",14,MUTED,false);add(feedback);g.setOnCheckedChangeListener((gr,id)->{if(answered==qi)return;int ix=-1;for(int z=0;z<opts.size();z++)if(opts.get(z).getId()==id)ix=z;answered=qi;if(ix>=0&&opts.get(ix).getText().equals(q[5])){score++;feedback.setText("Correct. Nice recall.");feedback.setTextColor(0xff36734b);}else{feedback.setText("Not quite. The answer is "+q[5]+".");feedback.setTextColor(ACC);}});add(button(qi==9?"See results":"Next question",()->{if(answered!=qi){toast("Choose an answer first.");return;}qi++;answered=-1;if(qi==Q.length)results();else showQ();}));}void results(){start("04    /    YOUR RESULT","Run complete","A quick measure of what stuck.");add(text(score+" / 10",54,ACC,true));add(text("Correct: "+score+"      Incorrect: "+(10-score),18,INK,true));add(button("Restart · reshuffle",()->startQuiz()));back();}
 // Stopwatch: elapsedRealtime makes paused/background intervals stable.
 void stopwatch(){start("05    /    TIME","Stopwatch","Monotonic timing · laps recorded locally for this screen");watch=text(format(running?SystemClock.elapsedRealtime()-base:elapsed),44,INK,true);watch.setGravity(Gravity.CENTER);watch.setPadding(0,dp(24),0,dp(24));add(watch);LinearLayout row=new LinearLayout(this);TextView startB=secondary(running?"Running":"Start / resume",()->{if(!running){base=SystemClock.elapsedRealtime()-elapsed;running=true;loop();stopwatch();}});TextView pauseB=secondary("Pause",()->{if(running){elapsed=SystemClock.elapsedRealtime()-base;running=false;handler.removeCallbacks(tick);stopwatch();}});TextView resetB=secondary("Reset",()->{running=false;elapsed=0;handler.removeCallbacks(tick);laps.clear();stopwatch();});row.addView(startB,new LinearLayout.LayoutParams(0,-2,1));row.addView(pauseB,new LinearLayout.LayoutParams(0,-2,1));row.addView(resetB,new LinearLayout.LayoutParams(0,-2,1));add(row);add(button("＋   Record lap",()->{if(!running){toast("Start the stopwatch before recording a lap.");return;}laps.add(format(SystemClock.elapsedRealtime()-base));stopwatch();}));add(label("LAPS   /   "+laps.size()));for(int i=laps.size()-1;i>=0;i--)add(text(String.format(Locale.US,"%02d     %s",i+1,laps.get(i)),16,INK,true));back();}String format(long ms){long cs=(ms%1000)/10,sec=(ms/1000)%60,min=(ms/60000)%60,hr=ms/3600000;return String.format(Locale.US,"%02d:%02d:%02d.%02d",hr,min,sec,cs);}void loop(){handler.removeCallbacks(tick);tick=new Runnable(){public void run(){if(running){watch.setText(format(SystemClock.elapsedRealtime()-base));handler.postDelayed(this,40);}}};handler.post(tick);}protected void onPause(){super.onPause();if(running){elapsed=SystemClock.elapsedRealtime()-base;running=false;resumeAfterPause=true;handler.removeCallbacks(tick);}}
 protected void onResume(){super.onResume();if(resumeAfterPause){resumeAfterPause=false;running=true;base=SystemClock.elapsedRealtime()-elapsed;if(watch!=null)loop();}}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putLong("watchElapsed",running?SystemClock.elapsedRealtime()-base:elapsed);out.putBoolean("watchRunning",running);out.putStringArrayList("watchLaps",laps);}
 protected void onRestoreInstanceState(Bundle in){super.onRestoreInstanceState(in);elapsed=in.getLong("watchElapsed",0);running=in.getBoolean("watchRunning",false);resumeAfterPause=running;ArrayList<String> saved=in.getStringArrayList("watchLaps");if(saved!=null){laps.clear();laps.addAll(saved);}}
}
